    "taylor_actions_label": "Ocena napake",
    "taylor_bound_help": "Najprej napovej: kako se napaka |f(x) − Tₙ(x)| spremeni, ko povečaš stopnjo? Nato pokaži Lagrangeevo oceno napake: zgornjo mejo za napako ob navedeni predpostavki o odvodu.",
    "taylor_hidden": "skrito",
