    "taylor_readout_series": "Vrsta pri n → ∞",
    "taylor_bound_unavailable": "ni prikazana (glej opombo)",
    "taylor_hypothesis_exp": "|f^(n+1)| ≤ M = max(e^c, e^x) med c in x, ker je e^t naraščajoča; ocena je M·|x − c|^(n+1)/(n+1)!",
    "taylor_hypothesis_sine": "|f^(n+1)| ≤ M = 1, ker so vsi odvodi funkcije sin x enaki ±sin x ali ±cos x; ocena je |x − c|^(n+1)/(n+1)!",
    "taylor_hypothesis_geometric": "|f^(n+1)| ≤ M = (n+1)!/(1 − max(c, x))^(n+2) med c in x, ker f^(n+1) narašča na x < 1; ocena je |x − c|^(n+1)/(1 − max(c, x))^(n+2)",
    "taylor_hypothesis_flat": "ni ocene: odvodi v c = 0 so vsi 0 in iz njih ni mogoče dobiti meje za ostanek",
    "taylor_series_everywhere": "Vrsta konvergira k f pri vsakem x.",
    "taylor_series_geometric_inside": "Vrsta konvergira k f za x med {value0} in {value1} (|x − c| < 1 − c); x je znotraj.",
    "taylor_series_geometric_outside": "Vrsta konvergira le za x med {value0} in {value1} (|x − c| < 1 − c); x je zunaj, tam ne konvergira.",
    "taylor_series_flat": "Vsi členi vrste so 0, zato vrsta konvergira, a k 0 in ne k f (za x > 0 je f(x) > 0).",
    "taylor_note": "Tₙ je končen polinom in vedno obstaja; ali neskončna Taylorjeva vrsta konvergira in h čemu, je ločeno vprašanje. Napaka je izračunana neposredno kot f(x) − Tₙ(x); vrednosti, manjše od 10⁻¹², so zaradi zaokroževanja prikazane kot 0.",
    "taylor_status_hidden": "Ocena napake je skrita: Tₙ in napaka sta prikazana, ocene pa še ni. Napovej, kako se napaka spreminja s stopnjo, in jo šele nato pokaži.",
    "taylor_status_revealed": "Prikazana je Lagrangeeva ocena ostanka s predpostavko o |f^(n+1)| med c in x; dejanska napaka ne presega ocene.",
    "taylor_status_inside": "Točka x je znotraj konvergenčnega intervala: tam se Tₙ(x) z večanjem n približuje f(x).",
    "taylor_status_outside": "Točka x je zunaj konvergenčnega intervala: vrsta tam ne konvergira in večja stopnja napake ne zmanjša.",
    "taylor_status_no_bound": "Ocena napake pri tej funkciji ni prikazana: vsi odvodi v c = 0 so 0, a je f(x) > 0 za x > 0, zato bi mejo za |f^(n+1)| morali dobiti iz odvodov drugje, tega pa ta prikaz ne modelira.",
    "taylor_status_bound_not_sharp": "Lagrangeeva ocena je tu veljavna, a ni ostra: lahko ostane velika ali celo naraste z večanjem n, čeprav gre dejanska napaka znotraj konvergenčnega intervala proti 0.",
    "taylor_status_flat": "Vsi koeficienti vrste v c = 0 so 0, zato je Tₙ = 0 pri vsaki stopnji. Za x > 0 je f(x) > 0, zato Tₙ funkcije ne približa, čeprav je f gladka: vrsta konvergira k 0, ne k f.",
