    "sequence_status_not_the_limit": "L = {value0} ni limita tega zaporedja (limita je {value1}), zato certifikata ni: za dovolj majhen ε členi od nobenega N naprej ne ostanejo v pasu okoli L.",
    "sequence_status_oscillating": "Ni certifikata: vrednosti 1 in −1 se ponavljata za vsakim N, tista od njiju, ki je dlje od L, pa je od L oddaljena za 1 + |L| = {value0} ≥ ε = {value1}, zato noben N ne deluje. Končno okno členov tega ne spremeni.",
