    "fixed_point_hyp_contraction_constant": "|T′(x)| = 1/2 za vsak x, zato po izreku o povprečni vrednosti velja |T(x) − T(y)| ≤ q |x − y| s q = 1/2 < 1.",
    "fixed_point_hyp_contraction_sine": "|T′(x)| = sin x ≤ sin 1 na [0; 1], zato po izreku o povprečni vrednosti velja |T(x) − T(y)| ≤ q |x − y| s q = sin 1 ≈ {value0} < 1.",
    "fixed_point_status_bound_a_priori": "A priori: |xₖ − x*| ≤ q^k/(1 − q) · |x₁ − x₀| = {value0}.",
