    "fixed_point_status_no_bound": "Pri T(x) = 1 − x je |T′| = 1, zato ni q < 1 in izrek o skrčitvi ne da ocene. To še ne pomeni, da iteracija divergira: manjka le zaključek iz izreka.",
    "fixed_point_status_cycle": "Dvocikel: približki izmenično zavzamejo {value0} in {value1} in se ne ustalijo. Vzrok je T(T(x)) = x. Ker je |T′| = 1, T ni skrčitev in izrek ne velja, kar samo po sebi divergence ne dokazuje.",
