    // Computational geometry: family and Batch 1 Demonstration titles and prompts.
    "computational_geometry": "Računska geometrija",
    "compgeo_orientation_title": "Orientacija treh točk",
    "prompt_compgeo_orientation_turn": "Premikaj točko r in opazuj, kdaj se zavoj p, q, r spremeni iz levega v desnega. Kaj pove predznak določenih izrazov in kje leži r, ko je vrednost enaka 0?",
    "prompt_compgeo_orientation_collinear": "Postavi r na premico skozi p in q. Zakaj je takrat vrednost natanko 0 in kako to loči zavoj v levo od zavoja v desno?",
    "compgeo_polygon_area_title": "Ploščina večkotnika",
    "prompt_compgeo_polygon_area_shoelace": "Premikaj oglišča in opazuj podpisano ploščino po obrazcu z determinantami (shoelace). Kaj se zgodi s predznakom, če obrneš zaporedje oglišč?",
    "prompt_compgeo_polygon_area_pick": "Preštej notranje in robne mrežne točke ter preveri Pickov izrek. Kdaj izrek velja in kaj se zgodi pri sebipresečnem večkotniku?",
    "compgeo_convex_hull_title": "Konveksna ovojnica",
    "prompt_compgeo_convex_hull_trace": "Pritiskaj Naslednji korak in napovej, katero točko bo algoritem naslednjo obdržal ali zavrgel. Kateri zavoj povzroči, da točka izpade iz ovojnice?",
    "prompt_compgeo_convex_hull_degenerate": "Postavi več točk na isto premico ali jih podvoji. Kako se ovojnica spremeni in kaj naredijo različni algoritmi v izrojenih primerih?",
    "compgeo_ear_clipping_title": "Triangulacija z rezanjem ušes",
    "prompt_compgeo_ear_clipping_ears": "Pritiskaj Naslednji korak in napovej, katero oglišče je uho. Kdaj je oglišče uho in zakaj ga lahko odrežemo?",
    "prompt_compgeo_ear_clipping_reflex": "Premakni oglišče tako, da postane vbočeno (reflektno). Kaj se zgodi z ušesi in zakaj ima vsak preprost večkotnik vsaj dve ušesi?",
    "compgeo_point_set_triangulation_title": "Triangulacija množice točk",
    "prompt_compgeo_point_set_triangulation_flip": "Zamenjaj diagonalo v štirikotniku dveh sosednjih trikotnikov. Kdaj je zamenjava mogoča in kako se spremenita najmanjši kot in število trikotnikov?",
    "prompt_compgeo_point_set_triangulation_count": "Dodaj ali premakni točke in preštej trikotnike ter robove. Zakaj sta števili za dano množico točk vedno enaki, ne glede na to, katero triangulacijo izbereš?",
    "compgeo_delaunay_title": "Delaunayeva triangulacija",
    "prompt_compgeo_delaunay_illegal": "Pritiskaj Naslednji korak in poišči nedovoljeno diagonalo. Zakaj leži četrta točka znotraj očrtanega kroga trikotnika in kaj stori zamenjava diagonale?",
    "prompt_compgeo_delaunay_cocircular": "Postavi štiri točke na skupno krožnico. Zakaj sta obe diagonali dovoljeni in zakaj Delaunayeva triangulacija ni enolična?",
    "compgeo_voronoi_title": "Voronojev diagram",
    "prompt_compgeo_voronoi_cell": "Izberi mesto in pokaži simetrale eno za drugo. Kako iz njih nastane celica mesta in zakaj je presek polravnin vedno konveksen?",
    "prompt_compgeo_voronoi_query": "Premakni točko poizvedbe in poglej, v kateri celici leži. Zakaj je najbližje mesto vedno mesto te celice in kaj pokaže vklopljena dualnost?",
    "compgeo_voronoi_degenerate_title": "Izrojena mesta",
    "prompt_compgeo_voronoi_degenerate_cocircular": "Postavi štiri mesta na skupno krožnico. Koliko Voronojevih oglišč dobiš, kakšna je njihova stopnja in zakaj sta obe diagonali dovoljeni?",
    "prompt_compgeo_voronoi_degenerate_collinear": "Postavi vsa mesta na isto premico. Zakaj Voronojevih oglišč ni, zakaj so celice pasovi in zakaj Delaunayeve triangulacije ni?",
    "compgeo_interval_sweep_title": "Pometanje intervalov",
    "prompt_compgeo_interval_sweep_events": "Pritiskaj Naslednji korak in opazuj pometalno premico. Kateri dogodki spremenijo stanje in kdaj se stanje poveča ali zmanjša?",
    "prompt_compgeo_interval_sweep_depth": "Premakni krajišče intervala. Kako se spremeni največje število hkrati odprtih intervalov in kje na premici nastopi?",
    "compgeo_segment_intersections_title": "Presečišča daljic",
    "prompt_compgeo_segment_intersections_neighbours": "Pritiskaj Naslednji korak in opazuj stanje pometalne premice. Kateri sosednji daljici moramo preveriti, ko daljica vstopi ali izstopi?",
    "prompt_compgeo_segment_intersections_swap": "Poišči dogodek, pri katerem se dve daljici v stanju zamenjata. Zakaj sta tik pred presečiščem sosednji in kaj se zgodi z novima sosedoma?",
    "compgeo_monotone_partition_title": "Razdelitev na monotone večkotnike",
    "prompt_compgeo_monotone_partition_vertex_types": "Pritiskaj Naslednji korak in opazuj vrste oglišč. Katera oglišča so razcepna in katera zlivna ter zakaj moramo vsako povezati z diagonalo?",
    "prompt_compgeo_monotone_partition_diagonals": "Premakni oglišče tako, da izgine razcepno oglišče. Kako se spremeni število diagonal in ali so deli res monotoni?",
    "compgeo_monotone_triangulation_title": "Triangulacija monotonega večkotnika",
    "prompt_compgeo_monotone_triangulation_stack": "Pritiskaj Naslednji korak in opazuj sklad. Kdaj z diagonalami odrežemo trikotnike in kdaj oglišče samo dodamo na sklad?",
    "prompt_compgeo_monotone_triangulation_chains": "Poišči oglišče, ki leži na drugi verigi kot vrh sklada. Zakaj ga lahko tedaj povežemo z vsemi oglišči v skladu?",
    "compgeo_fortune_title": "Fortunov algoritem",
    "prompt_compgeo_fortune_false_alarm": "Pritiskaj Naslednji korak in poišči črtkani, preklicani krog. Katero mesto leži v njem in zakaj se lok na obalni črti tedaj ne izniči?",
    "prompt_compgeo_fortune_delaunay_dual": "Pritiskaj Naslednji korak do konca in primerjaj nastali Voronojev diagram z Delaunayevo triangulacijo istih mest. Kateri trikotnik ustreza oglišču diagrama in zakaj v njegovem očrtanem krogu ni nobenega drugega mesta?",
