    "patch_elevate_v": "Dvigni stopnjo v v",
    "patch_elevate_help": "Višanje stopnje ohrani ploskev natančno, mreža pa dobi dodatno vrstico ali stolpec točk. Prejšnja mreža ostane narisana turkizno z dolgimi črtami, dokler mreže ne spremeniš.",
    "patch_elevate_maximum": "Stopnja v smeri {value0} je že 4, največja dovoljena, zato je ni mogoče več dvigniti.",
    "patch_show_pieces": "Pokaži dele krpe",
