    "patch_joins_title": "Stik dveh Bézierjevih krp",
    "prompt_patch_joins_c1": "Premikaj točke krpe A ob skupnem robu in opazuj, kako se prilagajata prvi dve vrstici krpe B. Zakaj teh točk ni mogoče premikati in kaj zagotavlja zveznost C1?",
    "prompt_patch_joins_g1": "Izberi stik G1 in spreminjaj razmerje α. Tangentni ravnini se ujemata, odvoda čez rob pa ne. Kako se to vidi na obeh puščicah in na poročilu o stiku?",
    "coons_patch_title": "Coonsova ploskev",
