    "patch_join_b_option_derived": "{value0} (izpeljana)",
    "patch_join_b_point_help": "Točke krpe A so P, točke krpe B so Q. Izberi točko krpe B s klikom v pogledu ali z indeksoma; točke krpe A urejaš v skupini »Kontrolna točka«.",
    "patch_join_b_derived_note": "Točka {value0} je izpeljana iz krpe A in ji sledi, zato je ni mogoče premikati, tudi ne s številskimi polji. Premakni točko krpe A ali izberi stik z manj pogoji.",
