    "patch_join_report_no_c0": "Krpi se ne stikata: robova ne sovpadata, zato niti C0 ne velja. Razmik robov je {value0}.",
    "patch_join_report_c0": "Samo C0 (po tem merilu): robova sovpadata, odvoda S_u čez rob pa se razlikujeta in nista v stalnem razmerju α. Stik zato ni C1 in ni G1 s stalnim razmerjem; če je kot med normalama večji od 0, ima ploskev ob robu ostri rob.",
    "patch_join_report_c0_planes": "C0 (po tem merilu): robova sovpadata in tudi tangentni ravnini ob robu sovpadata, vendar odvoda S_u čez rob nista v stalnem razmerju α. Stik zato ni C1 in ni G1 s stalnim razmerjem α; ostrega roba po tem merilu ni.",
    "patch_join_report_c0_no_ratio": "Samo C0: robova sovpadata, a je odvod S_u krpe A čez rob ničeln, krpe B pa ne. Razmerje odvodov α zato ne obstaja in G1 iz odvodov ni mogoče potrditi.",
    "patch_join_report_c1": "C1: odvoda S_u krp A in B čez rob sta enaka v vsaki točki roba (največja razlika {value0}). Zato se povsod, kjer sta določeni, ujemata tudi tangentni ravnini.",
    "patch_join_report_g1": "G1, ne C1: tangentni ravnini ob robu sovpadata povsod, kjer sta določeni, odvoda S_u pa nista enaka, ampak se razlikujeta za faktor α* = {value0}. Zveznost odvodov (C1) bi zahtevala α* = 1.",
    "patch_join_report_vanish": "Odvod S_u čez rob je ničeln na celem robu krpe A in krpe B. Odvoda sta si zato enaka (C1 velja), vendar tangentna ravnina ob robu ni določena z odvodom, zato iz tega ne moremo sklepati, da se tangentni ravnini ujemata (G1).",
    "patch_join_legend": "Mreža krpe A je zelena in polna, mreža krpe B opečnato oranžna in srednje črtkana (izpeljane točke so narisane enako kot ostale), skupni rob pa moder in poln. Modra polna puščica je S_u krpe A, rdeča polna puščica S_u krpe B v isti točki roba; obe sta narisani v istem merilu.",
