    "fortune_playback_note": "Predvajanje naredi en korak naenkrat in se ustavi ob koncu; ob odprtju je ustavljeno. Korak je en dogodek: pometalna premica se premakne navzdol, obalna črta je narisana približno (loki parabol), pike na njej so presečišča lokov, črte od oglišč do njih so že zarisani deli robov. Načrtovani krog je poln, njegova najnižja točka je romb; preklicani krog (lažni alarm) je črtkan, njegova najnižja točka je križec. Dogodek koraka je najdebelejši in označen tudi v seznamu: obroč okoli mesta ali njegov krog z obročem okoli novega oglišča.",
